<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {useQuasar} from 'quasar'
import {api,jsonPost} from './api'
import {language,tx} from './i18n'
const props=defineProps<{recipe:unknown;presets:any[]}>()
const emit=defineEmits(['recipe','refresh','demo'])
const q=useQuasar(),welcome=ref(false),help=ref(false),library=ref(false),batch=ref(false),search=ref(''),groupFilter=ref('')
const preferences=ref({language:'es',welcome_seen:false,export_format:'png'})
const error=ref(''),selected=ref<any>(null),name=ref(''),group=ref(''),busy=ref(false),job=ref<any>(null),batchIds=ref<string[]>([])
let poll:ReturnType<typeof setInterval>|undefined
async function savePreferences(){try{preferences.value.language=language.value;await api('/preferences',jsonPost(preferences.value,'PUT'))}catch(e){error.value=(e as Error).message}}
async function closeWelcome(){preferences.value.welcome_seen=true;await savePreferences();welcome.value=false}
async function demo(){busy.value=true;error.value='';try{const data=await(await api('/demo/load',jsonPost({}))).json();emit('demo',data);await closeWelcome()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function edit(preset:any){selected.value=preset;name.value=preset.name;group.value=preset.group??''}
async function save(){if(!selected.value)return;try{await api('/presets/'+selected.value.id,jsonPost({name:name.value,group:group.value,recipe:props.recipe},'PUT'));selected.value=null;emit('refresh')}catch(e){error.value=(e as Error).message}}
function remove(preset:any){q.dialog({title:tx('Eliminar preset','Delete preset'),message:preset.name,cancel:true}).onOk(async()=>{try{await api('/presets/'+preset.id,{method:'DELETE'});emit('refresh')}catch(e){error.value=(e as Error).message}})}
async function batchFiles(event:Event){
 const input=event.target as HTMLInputElement;const files=Array.from(input.files??[]);if(!files.length)return
 if(files.length>16){error.value=tx('Máximo 16 fotografías por lote','Maximum 16 photographs per batch');return}
 busy.value=true;error.value='';batchIds.value=[]
 try{for(const file of files){const data=new FormData();data.append('file',file);const image=await(await api('/images',{method:'POST',body:data})).json();batchIds.value.push(image.id)}}catch(e){error.value=(e as Error).message}finally{busy.value=false;input.value=''}
}
async function refreshJob(){if(job.value)try{job.value=await(await api('/jobs/'+job.value.id)).json()}catch(e){error.value=(e as Error).message}}
async function startBatch(){busy.value=true;error.value='';try{job.value=await(await api('/jobs',jsonPost({source_ids:batchIds.value,recipe:props.recipe,format:preferences.value.export_format}))).json()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function cancel(){try{job.value=await(await api('/jobs/'+job.value.id+'/cancel',jsonPost({}))).json()}catch(e){error.value=(e as Error).message}}
function openLibrary(){library.value=true}
defineExpose({openLibrary})
onMounted(async()=>{try{preferences.value=await(await api('/preferences')).json();language.value=preferences.value.language==='en'?'en':'es';welcome.value=!preferences.value.welcome_seen;const jobs=await(await api('/jobs')).json();job.value=jobs.at(-1)??null}catch(e){error.value=(e as Error).message}poll=setInterval(()=>{if(job.value&&['running','queued','cancelling'].includes(job.value.status))refreshJob()},700)})
onBeforeUnmount(()=>clearInterval(poll))
</script>
<template>
 <div class="beta-tools">
  <q-btn flat dense icon="collections_bookmark" :label="tx('Biblioteca','Library')" @click="library=true"/>
  <q-btn flat dense icon="photo_library" :label="tx('Lotes','Batch')" @click="batch=true"/>
  <q-btn flat dense icon="help_outline" :aria-label="tx('Ayuda y preferencias','Help and preferences')" @click="help=true"/>
 </div>
 <q-dialog v-model="welcome" persistent><q-card class="beta-dialog"><q-card-section><span class="small-kicker">COLOR STUDIO · BETA 0.2</span><h2>{{tx('Tu estilo, en tu equipo.','Your style, on your computer.')}}</h2><p>{{tx('Referencia → fotografía → analizar → ajustar → preset → exportar. Sin cuenta, telemetría ni servicios de imagen.','Reference → photo → analyze → adjust → preset → export. No account, telemetry or image services.')}}</p><p>{{tx('La demo usa fotografías CC0 de Sergej Majboroda / Poly Haven. No son resultados de investigación comercial.','The demo uses CC0 photographs by Sergej Majboroda / Poly Haven. These are not commercial research results.')}}</p><p>{{tx('Beta técnica sin firma: la calidad y el instalador siguen sujetos a validación.','Unsigned technical beta: quality and installer validation remain pending.')}}</p><q-select v-model="language" :options="['es','en']" :label="tx('Idioma','Language')"/></q-card-section><q-card-actions align="right"><q-btn flat :label="tx('Usar mis fotos','Use my photos')" @click="closeWelcome"/><q-btn color="primary" text-color="dark" :loading="busy" :label="tx('Probar demo local','Try local demo')" @click="demo"/></q-card-actions><q-banner v-if="error">{{error}}</q-banner></q-card></q-dialog>
 <q-dialog v-model="library"><q-card class="beta-dialog"><q-card-section><h2>{{tx('Biblioteca de estilos','Style library')}}</h2><q-input v-model="search" :label="tx('Buscar nombre','Search name')"/><q-input v-model="groupFilter" :label="tx('Filtrar grupo','Filter group')"/><div v-for="preset in presets.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())&&(p.group??'').toLowerCase().includes(groupFilter.toLowerCase()))" :key="preset.id" class="library-row"><div><strong>{{preset.name}}</strong><small>{{preset.group||tx('Sin grupo','Ungrouped')}}</small></div><q-btn flat icon="play_arrow" :aria-label="tx('Aplicar','Apply')" @click="emit('recipe',preset.recipe)"/><q-btn flat icon="edit" :aria-label="tx('Editar','Edit')" @click="edit(preset)"/><q-btn flat icon="delete_outline" :aria-label="tx('Eliminar','Delete')" @click="remove(preset)"/></div><div v-if="selected"><q-input v-model="name" :label="tx('Nombre','Name')" maxlength="80"/><q-input v-model="group" :label="tx('Grupo','Group')" maxlength="40"/><p>{{tx('Guardar reemplaza la receta del preset por los ajustes actuales.','Saving replaces the preset recipe with the current adjustments.')}}</p><q-btn :label="tx('Guardar cambios','Save changes')" :disable="!name.trim()" @click="save"/></div><q-banner v-if="error">{{error}}</q-banner></q-card-section><q-card-actions align="right"><q-btn flat v-close-popup :label="tx('Cerrar','Close')"/></q-card-actions></q-card></q-dialog>
 <q-dialog v-model="batch"><q-card class="beta-dialog"><q-card-section><h2>{{tx('Un estilo, varias fotografías','One style, several photographs')}}</h2><p>{{tx('Aplica exactamente la receta global actual a cada foto; no recalcula el matching para cada imagen. Hasta 16 archivos, originales intactos.','Applies exactly the current global recipe to every photograph, without refitting each image. Up to 16 files; originals are preserved.')}}</p><input type="file" multiple accept="image/jpeg,image/png" :aria-label="tx('Añadir fotografías al lote','Add batch photographs')" :disabled="busy" @change="batchFiles"><p>{{batchIds.length}} {{tx('fotografías listas','photographs ready')}}</p><q-select v-model="preferences.export_format" :options="['png','jpg']" :label="tx('Formato','Format')" @update:model-value="savePreferences"/><q-btn color="primary" text-color="dark" :loading="busy" :disable="!batchIds.length||['running','queued','cancelling'].includes(job?.status)" :label="tx('Procesar lote','Process batch')" @click="startBatch"/><div v-if="job"><p>{{job.status}} · {{job.completed}} / {{job.total}}</p><q-linear-progress :value="job.progress/100"/><q-btn v-if="['running','queued'].includes(job.status)" flat :label="tx('Cancelar','Cancel')" @click="cancel"/><p>{{job.message}}</p><div v-for="item in job.items" :key="item.index"><a v-if="item.status==='completed'" :href="`/api/jobs/${job.id}/files/${item.index}`" download>{{item.filename}}</a><span v-else>{{tx('Archivo fallido','Failed input')}} {{item.index+1}}</span></div><p v-if="['failed','cancelled','interrupted','completed_with_errors'].includes(job.status)">{{tx('Los resultados terminados se conservan. Puedes iniciar un lote nuevo sin sobrescribirlos.','Completed results remain available. Start a new batch without overwriting them.')}}</p></div><q-banner v-if="error">{{error}}</q-banner></q-card-section><q-card-actions align="right"><q-btn flat v-close-popup :label="tx('Cerrar','Close')"/></q-card-actions></q-card></q-dialog>
 <q-dialog v-model="help"><q-card class="beta-dialog"><q-card-section><h2>{{tx('Ayuda y preferencias','Help and preferences')}}</h2><q-select v-model="language" :options="['es','en']" :label="tx('Idioma','Language')" @update:model-value="savePreferences"/><p><a href="/feedback/" target="_blank">{{tx('Feedback privado sin envío automático','Private feedback, no automatic submission')}}</a></p><p>Color Studio 0.3.0-beta.1 · {{tx('nombre provisional','provisional name')}}</p><p>{{tx('Novedades: lotes cancelables, grupos y edición de presets, preferencias persistentes y sesión local protegida.','New: cancellable batches, preset groups and editing, persistent preferences and protected local session.')}}</p><p>{{tx('JPG/PNG8 sRGB, 24 MP, 32 MiB por archivo. Sin RAW, Log, HDR, vídeo, IA o telemetría.','sRGB JPG/PNG8, 24 MP, 32 MiB per file. No RAW, Log, HDR, video, AI or telemetry.')}}</p><p>{{tx('Importa dos imágenes y pulsa Analizar y transferir. El deslizador compara la misma fotografía. Intensidad de color cero desactiva Color Match; el acabado tiene su propio interruptor. Guarda tu preset antes de cerrar la sesión.','Import two images and choose Analyze and transfer. The slider compares the same photograph. Zero colour strength disables Color Match; finishing has its own bypass. Save your preset before closing.')}}</p><p>{{tx('Las LUT son mapas globales sRGB de 33³. No transportan máscaras ni adaptación por fotografía. La compatibilidad con editores externos debe comprobarse.','LUTs are global 33³ sRGB maps. They do not carry masks or per-photo adaptation. External editor compatibility must be verified.')}}</p><q-btn flat :label="tx('Volver a la bienvenida','Show welcome')" @click="welcome=true"/></q-card-section><q-card-actions align="right"><q-btn flat v-close-popup :label="tx('Cerrar','Close')"/></q-card-actions></q-card></q-dialog>
</template>
